// userScanMapperNullable maps the preloaded user
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func userScanMapperNullable(prefix string) scan.Mapper[*User] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*User, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *userPreloadBuf) any
		}
		targets := make([]target, 0, 6)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.ID }})
			case "username":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.Username }})
			case "password_hash":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.PasswordHash }})
			case "role":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.Role }})
			case "created_at":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *userPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(userPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*User, error) {
				buf := link.(*userPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Username.IsValue()) &&
					!(buf.PasswordHash.IsValue()) &&
					!(buf.Role.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) {
					return nil, nil
				}

				o := new(User)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Username.IsValue() {
					o.Username = buf.Username.MustGet()
				}
				if buf.PasswordHash.IsValue() {
					o.PasswordHash = buf.PasswordHash.MustGet()
				}
				if buf.Role.IsValue() {
					o.Role = buf.Role.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *User) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Sessions":
		rels, ok := retrieved.(SessionSlice)
		if !ok {
			return fmt.Errorf("user cannot load %T as %q", retrieved, name)
		}

		o.R.Sessions = rels
		o.R.Loaded.Sessions = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.User = o
				rel.R.Loaded.User = true
			}
		}
		return nil
	default:
		return fmt.Errorf("user has no relationship %q", name)
	}
}

type userPreloader struct{}

func buildUserPreloader() userPreloader {
	return userPreloader{}
}

type userThenLoader[Q orm.Loadable] struct {
	Sessions func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildUserThenLoader[Q orm.Loadable]() userThenLoader[Q] {
	type SessionsLoadInterface interface {
		LoadSessions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return userThenLoader[Q]{
		Sessions: thenLoadBuilder[Q](
			"Sessions",
			func(ctx context.Context, exec bob.Executor, retrieved SessionsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadSessions(ctx, exec, mods...)
			},
		),
	}
}

// LoadSessions loads the user's Sessions into the .R struct
func (o *User) LoadSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Sessions = nil
	o.R.Loaded.Sessions = false

	related, err := o.Sessions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.User = o
		rel.R.Loaded.User = true
	}

	o.R.Sessions = related
	o.R.Loaded.Sessions = true
	return nil
}

// LoadSessions loads the user's Sessions into the .R struct
func (os UserSlice) LoadSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	sessions, err := os.Sessions(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Sessions = nil
		o.R.Loaded.Sessions = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	userByKey := make(map[string][]*User, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		userByKey[o.ID] = append(userByKey[o.ID], o)
	}

	for _, rel := range sessions {

		owners, ok := userByKey[rel.UserID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.User = o
			rel.R.Loaded.User = true

			o.R.Sessions = append(o.R.Sessions, rel)

		}
	}

	return nil
}

// userC is where relationship counts are stored.
type userC struct {
	Sessions *int64
}

// PreloadCount sets a count in the C struct by name
func (o *User) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Sessions":
		o.C.Sessions = &count
	}
	return nil
}

type userCountPreloader struct {
	Sessions func(...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader
}

func buildUserCountPreloader() userCountPreloader {
	return userCountPreloader{
		Sessions: func(mods ...bob.Mod[*dialect.SelectQuery]) sqlite.Preloader {
			return countPreloader[*User]("Sessions", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = Users.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(sqlite.Raw("count(*)")),

					sm.From(Sessions.NameAsExpr()),
					sm.Where(sqlite.Quote(Sessions.Alias(), "user_id").EQ(sqlite.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return sqlite.Group(sqlite.Select(subqueryMods...).Expression)
			})
		},
	}
}

type userCountThenLoader[Q orm.Loadable] struct {
	Sessions func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildUserCountThenLoader[Q orm.Loadable]() userCountThenLoader[Q] {
	type SessionsCountInterface interface {
		LoadCountSessions(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return userCountThenLoader[Q]{
		Sessions: countThenLoadBuilder[Q](
			"Sessions",
			func(ctx context.Context, exec bob.Executor, retrieved SessionsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountSessions(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountSessions loads the count of Sessions into the C struct
func (o *User) LoadCountSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.Sessions(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.Sessions = &count
	return nil
}

// LoadCountSessions loads the count of Sessions for a slice in a single batch query
func (os UserSlice) LoadCountSessions(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			Sessions.Columns.UserID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(Sessions.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(Sessions.Columns.UserID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(Sessions.Columns.UserID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.Sessions = &count
	}

	return nil
}

type userJoins[Q dialect.Joinable] struct {
	typ      string
	Sessions modAs[Q, sessionColumns]
}

func (j userJoins[Q]) aliasedAs(alias string) userJoins[Q] {
	return buildUserJoins[Q](buildUserColumns(alias), j.typ)
}

func buildUserJoins[Q dialect.Joinable](cols userColumns, typ string) userJoins[Q] {
	return userJoins[Q]{
		typ: typ,
		Sessions: modAs[Q, sessionColumns]{
			c: Sessions.Columns,
			f: func(to sessionColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Sessions.NameExpr().As(to.Alias())).On(
						to.UserID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
